class BytesIOCopy:
    """A binary buffer that copies everything written to it into another
    buffer.

    Unlike a plain ``io.BytesIO``, this is backed by a real (temporary) OS
    file, so it exposes a working ``fileno()``. That allows code under test
    to pass the captured stream to APIs, such as :func:`subprocess.run`,
    that require a real file descriptor.

    .. versionadded:: 8.2

    .. versionchanged:: 8.3.3
        Backed by a temporary file instead of an in-memory buffer so that
        ``fileno()`` works. :issue:`2522`
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        self._file = tempfile.TemporaryFile()
        self.copy_to = copy_to

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._file, name)

    def fileno(self) -> int:
        return self._file.fileno()

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return self._file.write(b)

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        try:
            return self._file.read()
        finally:
            self._file.seek(pos)

